package run.ikaros.music;
import java.util.UUID; import org.springframework.stereotype.Service; import run.ikaros.common.NotFoundException; import run.ikaros.storage.api.AttachmentView; import run.ikaros.storage.api.StorageService; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@Service public class PersistentMusicDuplicateService implements MusicDuplicateService { private final StorageService storage; private final MusicAudioSourceRepository sources; private final MusicTrackRepository tracks; public PersistentMusicDuplicateService(StorageService storage,MusicAudioSourceRepository sources,MusicTrackRepository tracks){this.storage=storage;this.sources=sources;this.tracks=tracks;} @Override public Mono<java.util.List<MusicDuplicateView>> find(UUID ownerId,UUID attachmentId){return storage.get(ownerId,attachmentId).switchIfEmpty(Mono.error(new NotFoundException("附件不存在或无权访问"))).flatMap(attachment->storage.findByContentIdentity(ownerId,attachment.sha256(),attachment.sizeBytes()).flatMapMany(Flux::fromIterable).filter(other->!other.id().equals(attachmentId)).flatMap(other->sources.findAllByOwnerIdAndAttachmentId(ownerId,other.id()).flatMap(source->tracks.findById(source.trackId()).filter(track->track.ownerId().equals(ownerId)).map(track->new MusicDuplicateView(other.id(),track.id(),track.title(),other.sha256(),other.sizeBytes())))).take(100).collectList());} }
